package vn.unlimit.vpngate.utils

import de.blinkt.openvpn.VpnProfile

/**
 * Restores the username/password half of a VPN Gate OpenVPN profile.
 *
 * ## Why this exists
 *
 * VPN Gate publishes the OpenVPN profile generated by the SoftEther Server
 * Manager. That template ships a **dummy** client certificate/key pair and
 * leaves the authentication directive commented out:
 *
 * ```
 * <cert>
 * -----BEGIN CERTIFICATE-----   (dummy pair, identical on every server)
 * ...
 * <key>
 * -----BEGIN RSA PRIVATE KEY-----
 * ...
 * #auth-user-pass               <-- commented out
 * ```
 *
 * The SoftEther "OpenVPN Server Compatible Function" authenticates the user
 * against the hub account `vpn` / `vpn`; the embedded certificate is only there
 * because some clients (notably the iOS OpenVPN client) refuse a profile that
 * carries no client certificate at all. It is not a credential.
 *
 * `ConfigParser` therefore derives [VpnProfile.TYPE_CERTIFICATES] for every
 * single VPN Gate profile, and the core never emits
 * `>PASSWORD:Need 'Auth'`. `OpenVpnManagementThread` only delivers
 * `mUsername` / `getPasswordAuth()` in response to that request, so no
 * credentials are ever sent. The server completes the TLS handshake, receives
 * `PUSH_REQUEST`, finds no authenticated user, and answers
 * `AUTH: Received control message: AUTH_FAILED` — the tunnel is torn down
 * before `tun0` is ever created.
 *
 * A tunnel that never exists cannot carry the server-list refresh, which is
 * why "update the server list" appeared to fail only under OpenVPN: the
 * collector had no TUNNEL rung to climb and fell back to the physical
 * interface.
 *
 * ## What this does
 *
 * Promotes a certificate-only profile to
 * [VpnProfile.TYPE_USERPASS_CERTIFICATES] and fills in the hub account, so
 * `VpnProfile.getConfigFile()` emits `auth-user-pass` and the management
 * thread can answer the core's credential request.
 *
 * It is deliberately conservative:
 *  - a profile that already carries a username (an inline `<auth-user-pass>`
 *    block, or a caller that set one) is left untouched;
 *  - only [VpnProfile.TYPE_CERTIFICATES] is promoted, and only when both the
 *    inline certificate and key survived parsing — otherwise the promotion
 *    would drop the certificate from the generated config;
 *  - every other authentication type is returned unchanged.
 *
 * This object is deliberately free of `android.util.Log` so it stays a plain
 * JVM unit under `:app:testProDebugUnitTest`; callers log the result.
 */
object OpenVpnAuthDefaults {

    /** VPN Gate hub account used by the SoftEther OpenVPN compatibility layer. */
    const val VPN_GATE_USERNAME = "vpn"

    /** Password matching [VPN_GATE_USERNAME]. */
    const val VPN_GATE_PASSWORD = "vpn"

    /**
     * Fills in the VPN Gate hub account on [profile] when the parsed profile is
     * certificate-only.
     *
     * @return `true` when the profile was modified, `false` when it was left
     *   alone (already has credentials, is not a certificate profile, or is
     *   missing the embedded pair the promotion depends on).
     */
    fun applyIfMissing(profile: VpnProfile): Boolean {
        if (!profile.mUsername.isNullOrEmpty()) {
            // An inline <auth-user-pass> block already supplied credentials.
            return false
        }
        if (profile.mAuthenticationType != VpnProfile.TYPE_CERTIFICATES) {
            // Either already a TYPE_USERPASS_* profile (credentials present but
            // no username, which the caller must resolve) or a type this helper
            // does not understand. Do not guess.
            return false
        }
        if (profile.mClientCertFilename.isNullOrEmpty() || profile.mClientKeyFilename.isNullOrEmpty()) {
            // Without the embedded pair, promoting to *_CERTIFICATES would make
            // VpnProfile.getConfigFile() emit no client certificate at all.
            return false
        }

        profile.mAuthenticationType = VpnProfile.TYPE_USERPASS_CERTIFICATES
        profile.mUsername = VPN_GATE_USERNAME
        profile.mPassword = VPN_GATE_PASSWORD
        return true
    }
}
